WITH cleaned AS (SELECT *, LOWER(city) AS city_lower, REGEXP_REPLACE(supplier_name, ' ', '_') AS supplier_name_slug FROM suppliers WHERE city IS NOT NULL AND country IN ('DE', 'SG', 'UK')) SELECT country, city, COUNT(*) FILTER (WHERE country = 'UK') AS uk_rows, ROUND(AVG(rating), 2) AS avg_rating, SUM(rating) AS total_rating FROM cleaned GROUP BY country, city ORDER BY city DESC NULLS FIRST;
